ALTER TABLE chapters ADD COLUMN page_count INTEGER NOT NULL DEFAULT 0 CHECK(page_count>=0);
UPDATE chapters SET page_count=(SELECT count(*) FROM chapter_pages WHERE chapter_id=chapters.id);
CREATE TRIGGER page_count_insert AFTER INSERT ON chapter_pages BEGIN UPDATE chapters SET page_count=page_count+1 WHERE id=NEW.chapter_id; END;
CREATE TRIGGER page_count_delete AFTER DELETE ON chapter_pages BEGIN UPDATE chapters SET page_count=page_count-1 WHERE id=OLD.chapter_id; END;
CREATE TRIGGER page_count_move AFTER UPDATE OF chapter_id ON chapter_pages WHEN OLD.chapter_id<>NEW.chapter_id BEGIN UPDATE chapters SET page_count=page_count-1 WHERE id=OLD.chapter_id; UPDATE chapters SET page_count=page_count+1 WHERE id=NEW.chapter_id; END;
CREATE TRIGGER pages_owner_insert BEFORE INSERT ON chapter_pages BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM assets a JOIN chapters c ON c.id=NEW.chapter_id WHERE a.id=NEW.asset_id AND a.chapter_id=c.id AND a.title_id=c.title_id) THEN RAISE(ABORT,'Page asset must belong to chapter and title') END; END;
CREATE TRIGGER pages_owner_update BEFORE UPDATE ON chapter_pages BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM assets a JOIN chapters c ON c.id=NEW.chapter_id WHERE a.id=NEW.asset_id AND a.chapter_id=c.id AND a.title_id=c.title_id) THEN RAISE(ABORT,'Page asset must belong to chapter and title') END; END;
CREATE TRIGGER pages_values_insert BEFORE INSERT ON chapter_pages BEGIN SELECT CASE WHEN NEW.position<0 OR NEW.rotation NOT IN (0,90,180,270) THEN RAISE(ABORT,'Invalid page position or rotation') END; END;
CREATE TRIGGER pages_values_update BEFORE UPDATE ON chapter_pages BEGIN SELECT CASE WHEN NEW.position<0 OR NEW.rotation NOT IN (0,90,180,270) THEN RAISE(ABORT,'Invalid page position or rotation') END; END;
CREATE TRIGGER title_values_insert BEFORE INSERT ON titles BEGIN SELECT CASE WHEN NEW.type NOT IN ('Manga','Manhwa','Manhua','Webtoon') OR NEW.status NOT IN ('Ongoing','Completed','Hiatus','Cancelled') OR NEW.direction NOT IN ('ltr','rtl','vertical') OR (NEW.year IS NOT NULL AND (NEW.year<1000 OR NEW.year>2200)) THEN RAISE(ABORT,'Invalid title metadata') END; END;
CREATE TRIGGER title_values_update BEFORE UPDATE ON titles BEGIN SELECT CASE WHEN NEW.type NOT IN ('Manga','Manhwa','Manhua','Webtoon') OR NEW.status NOT IN ('Ongoing','Completed','Hiatus','Cancelled') OR NEW.direction NOT IN ('ltr','rtl','vertical') OR (NEW.year IS NOT NULL AND (NEW.year<1000 OR NEW.year>2200)) THEN RAISE(ABORT,'Invalid title metadata') END; END;
